import{_ as a,o,c as e,a2 as r}from"./chunks/framework.CXsxtpvq.js";const b=JSON.parse('{"title":"문제 해결","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/troubleshooting.md","filePath":"ko/guide/troubleshooting.md"}'),d={name:"ko/guide/troubleshooting.md"};function i(l,t,h,n,s,c){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="문제-해결" tabindex="-1">문제 해결 <a class="header-anchor" href="#문제-해결" aria-label="Permalink to &quot;문제 해결&quot;">​</a></h1><h2 id="comfyui에-연결할-수-없음" tabindex="-1">ComfyUI에 연결할 수 없음 <a class="header-anchor" href="#comfyui에-연결할-수-없음" aria-label="Permalink to &quot;ComfyUI에 연결할 수 없음&quot;">​</a></h2><p>오른쪽 위 연결 표시가 빨간색이면 ComfyUI가 꺼져 있거나 주소가 다릅니다. ComfyUI를 켜고 <strong>설정 › ComfyUI 연결 정보</strong>의 주소를 확인하세요.</p><h2 id="모델이나-노드가-목록에-없음" tabindex="-1">모델이나 노드가 &quot;목록에 없음&quot; <a class="header-anchor" href="#모델이나-노드가-목록에-없음" aria-label="Permalink to &quot;모델이나 노드가 &quot;목록에 없음&quot;&quot;">​</a></h2><p>모델이나 커스텀 노드를 설치한 뒤에는 ComfyUI를 재시작하고 Asset Studio 페이지를 새로고침하세요. 이미지 도구는 필요한 노드가 없으면 그 이름을 알려 줍니다. 필요한 노드와 모델은 <a href="https://github.com/kiritype/asset-studio#dependencies" target="_blank" rel="noreferrer">README의 의존성</a>을 보세요.</p><h2 id="대기열이-멈춤" tabindex="-1">대기열이 멈춤 <a class="header-anchor" href="#대기열이-멈춤" aria-label="Permalink to &quot;대기열이 멈춤&quot;">​</a></h2><p>작업이 실패하면 나머지 작업을 잃지 않도록 대기열이 일시정지합니다. 대기열 창에서 실패한 작업의 오류를 읽고 원인을 고친 뒤 다시 시작하세요.</p><h2 id="생성이-시작되지-않고-기다림" tabindex="-1">생성이 시작되지 않고 기다림 <a class="header-anchor" href="#생성이-시작되지-않고-기다림" aria-label="Permalink to &quot;생성이 시작되지 않고 기다림&quot;">​</a></h2><p>다른 작업(LoRA 학습, VLM 검수)이 GPU를 쓰고 있거나 <strong>GPU 대기 조건</strong>에 걸린 경우입니다. 오른쪽 위 연결 표시와 <strong>설정 › GPU 사용</strong>에서 기다리는 이유를 볼 수 있습니다.</p><h2 id="lora를-켰더니-구도가-이상해짐" tabindex="-1">LoRA를 켰더니 구도가 이상해짐 <a class="header-anchor" href="#lora를-켰더니-구도가-이상해짐" aria-label="Permalink to &quot;LoRA를 켰더니 구도가 이상해짐&quot;">​</a></h2><p>데이터셋이 작거나 한쪽으로 치우치면 LoRA가 구도까지 배웁니다(인물이 둘로 나오거나 지나치게 가까워지는 등). <a href="./lora#좋은-데이터셋">LoRA 학습의 좋은 데이터셋</a>을 참고해 이미지를 늘리고, 강도를 낮추거나 이른 에폭을 써 보세요.</p><h2 id="로그-파일" tabindex="-1">로그 파일 <a class="header-anchor" href="#로그-파일" aria-label="Permalink to &quot;로그 파일&quot;">​</a></h2><table tabindex="0"><thead><tr><th>파일</th><th>내용</th></tr></thead><tbody><tr><td><code>logs/studio.log</code></td><td>서버</td></tr><tr><td><code>logs/launcher.log</code></td><td>시작·종료</td></tr><tr><td><code>logs/lora/&lt;학습 이름&gt;/trainer.log</code></td><td>LoRA 학습</td></tr></tbody></table><h2 id="내-데이터-백업" tabindex="-1">내 데이터 백업 <a class="header-anchor" href="#내-데이터-백업" aria-label="Permalink to &quot;내 데이터 백업&quot;">​</a></h2><p><code>data/</code>(라이브러리, 검수, 데이터셋, LoRA 기록, 설정)와 <code>outputs/</code>(이미지)를 백업하세요. 두 폴더는 git 저장소에 포함되지 않습니다.</p>',15)])])}const f=a(d,[["render",i]]);export{b as __pageData,f as default};
